SysMLParser::SysMLParser(TokenStream *input) : SysMLParser(input, antlr4::atn::ParserATNSimulatorOptions()) {}

SysMLParser::SysMLParser(TokenStream *input, const antlr4::atn::ParserATNSimulatorOptions &options) : Parser(input) {
  SysMLParser::initialize();
  _interpreter = new atn::ParserATNSimulator(this, *sysmlParserStaticData->atn, sysmlParserStaticData->decisionToDFA, sysmlParserStaticData->sharedContextCache, options);
}

SysMLParser::~SysMLParser() {
  delete _interpreter;
}

const atn::ATN& SysMLParser::getATN() const {
  return *sysmlParserStaticData->atn;
}

std::string SysMLParser::getGrammarFileName() const {
  return "SysML.g4";
}

const std::vector<std::string>& SysMLParser::getRuleNames() const {
  return sysmlParserStaticData->ruleNames;
}

const dfa::Vocabulary& SysMLParser::getVocabulary() const {
  return sysmlParserStaticData->vocabulary;
}

antlr4::atn::SerializedATNView SysMLParser::getSerializedATN() const {
  return sysmlParserStaticData->serializedATN;
}


