SysMLParser::FileContext::FileContext(ParserRuleContext *parent, size_t invokingState)
  : ParserRuleContext(parent, invokingState) {
}

tree::TerminalNode* SysMLParser::FileContext::EOF() {
  return getToken(SysMLParser::EOF, 0);
}

std::vector<SysMLParser::PackageContext *> SysMLParser::FileContext::package() {
  return getRuleContexts<SysMLParser::PackageContext>();
}

SysMLParser::PackageContext* SysMLParser::FileContext::package(size_t i) {
  return getRuleContext<SysMLParser::PackageContext>(i);
}


size_t SysMLParser::FileContext::getRuleIndex() const {
  return SysMLParser::RuleFile;
}


std::any SysMLParser::FileContext::accept(tree::ParseTreeVisitor *visitor) {
  if (auto parserVisitor = dynamic_cast<SysMLVisitor*>(visitor))
    return parserVisitor->visitFile(this);
  else
    return visitor->visitChildren(this);
}

